<?php require_once __DIR__.'/config/auth.php';$pageTitle='Kategori';if(isset($_GET['hapus'])){try{$pdo->prepare("DELETE FROM kategori WHERE id=?")->execute([(int)$_GET['hapus']]);}catch(Exception $e){}header('Location:kategori.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO kategori(nama,jenis) VALUES(?,?)")->execute([trim($_POST['nama']),$_POST['jenis']]);header('Location:kategori.php');exit;}$data=$pdo->query("SELECT * FROM kategori ORDER BY jenis,nama")->fetchAll();include __DIR__.'/partials/header.php';?><div class="card p-4 mb-4"><h5>Tambah Kategori</h5><form method="post" class="row g-2"><div class="col-md-5"><input name="nama" class="form-control" placeholder="Nama kategori" required></div><div class="col-md-3"><select name="jenis" class="form-select"><option value="pemasukan">Pemasukan</option><option value="pengeluaran">Pengeluaran</option></select></div><div class="col-md-2"><button class="btn btn-success">Tambah</button></div></form></div><div class="card p-4"><h5>Daftar Kategori</h5><table class="table"><thead><tr><th>Nama</th><th>Jenis</th><th>Aksi</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=htmlspecialchars($r['nama'])?></td><td><?=ucfirst($r['jenis'])?></td><td><a class="btn btn-sm btn-outline-danger" href="?hapus=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div><?php include __DIR__.'/partials/footer.php';?>